package upload
import ("net/http"; "scan-session-api/internal/staging")
func Receive(w http.ResponseWriter, r *http.Request) {
    dir, err := staging.Create()
    if err != nil { http.Error(w, "STAGE_UNAVAILABLE", 503); return }
    defer staging.DiscardWorkspace(dir)
    if err := staging.Commit(dir); err != nil { http.Error(w, "SCAN_COMMIT_FAILED", 500); return }
    w.WriteHeader(202)
}

