package staging
import "os"
func Create() (string, error) { return os.MkdirTemp("", "scan-") }
func DiscardWorkspace(dir string) error { return os.RemoveAll(dir) }

files.internal/staging/commit.go:
package staging
import "os"
func Commit(dir string) error { return os.WriteFile(dir+"/accepted", []byte("queued\n"), 0600) }
